import React, { useState } from "react";
import { NavLink, useNavigate, useLocation } from "react-router-dom";
import { Menu, X } from "lucide-react";
import logo from "../images/logo.png";

const Navbar = () => {
  const links = [
    { to: "/", label: "Home" },
    { to: "/courses", label: "Courses" },
    { to: "/teachers", label: "Teachers" },
    { to: "/about", label: "About Us" },
  ];

  const navigate = useNavigate();
  const location = useLocation();
  const [isOpen, setIsOpen] = useState(false);

  const handleClick = () => {
    navigate("/signup");
    setIsOpen(false);
  };

  return (
    <header className="bg-[#d49539] h-[100px] max-h-[100px] relative z-50">
      <div className="max-w-7xl mx-auto px-4 md:px-8 lg:px-16 py-3 md:py-4 flex items-center justify-between h-full">
        {/* Logo */}
        <div className="w-[80px] md:w-[90px] -mt-[10px] cursor-pointer" onClick={() => navigate("/")}>
          <img src={logo} alt="Success Mentor logo" className="w-full h-full object-contain" />
        </div>

        {/* Mobile Hamburger Button */}
        <button
          onClick={() => setIsOpen(!isOpen)}
          className="md:hidden p-2 text-[#304b62] hover:bg-black/10 rounded-lg focus:outline-none"
          aria-label="Toggle Navigation Menu"
        >
          {isOpen ? <X size={28} /> : <Menu size={28} />}
        </button>

        {/* Desktop Nav Links */}
        <nav className="hidden md:flex items-center gap-2 lg:gap-6 -mt-[10px]">
          {links.map((link) => {
            const isActive = location.pathname === link.to;
            return (
              <NavLink
                to={link.to}
                key={link.to}
                className="relative py-2 px-3 font-bold text-sm lg:text-lg text-[#304b62] hover:opacity-85 transition-colors"
              >
                {link.label}
                {isActive && (
                  <span className="absolute bottom-[-16px] left-0 right-0 h-[8px] bg-[#304b62] rounded-t-[7px]" />
                )}
              </NavLink>
            );
          })}
        </nav>

        {/* Desktop Admission Button */}
        <button
          onClick={handleClick}
          className="hidden md:inline-flex items-center justify-center bg-[#304b62] hover:bg-[#253b4e] text-white font-bold px-6 h-[50px] rounded-md transition-colors shadow-sm ml-4"
        >
          Admission Now
        </button>
      </div>

      {/* Mobile Drawer */}
      {isOpen && (
        <div className="fixed inset-0 z-50 md:hidden flex justify-end">
          {/* Overlay */}
          <div
            className="fixed inset-0 bg-black/50 transition-opacity"
            onClick={() => setIsOpen(false)}
          />
          {/* Drawer Content */}
          <div className="relative w-64 max-w-[80%] bg-[#d49539] h-full p-6 shadow-2xl flex flex-col z-10 animate-in slide-in-from-right">
            <div className="flex justify-between items-center pb-4 border-b border-[#304b62]/20">
              <span className="font-bold text-xl text-[#304b62]">Menu</span>
              <button
                onClick={() => setIsOpen(false)}
                className="p-1 rounded text-[#304b62] hover:bg-black/10"
              >
                <X size={24} />
              </button>
            </div>

            <div className="flex flex-col gap-4 mt-6">
              {links.map((link) => (
                <NavLink
                  to={link.to}
                  key={link.to}
                  onClick={() => setIsOpen(false)}
                  className={`font-semibold text-lg py-2 px-3 rounded-md transition-colors ${
                    location.pathname === link.to
                      ? "bg-[#304b62] text-white"
                      : "text-[#304b62] hover:bg-black/10"
                  }`}
                >
                  {link.label}
                </NavLink>
              ))}

              <button
                onClick={handleClick}
                className="w-full mt-4 bg-[#304b62] hover:bg-[#253b4e] text-white font-bold h-[50px] rounded-md transition-colors shadow-md"
              >
                Admission Now
              </button>
            </div>
          </div>
        </div>
      )}
    </header>
  );
};

export default Navbar;
